        bra         z, L_x1s3p_ready32_refuse
        cp.l        W3, #512
        bra         gtu, L_x1s3p_ready32_refuse
        clr         W4
        mov.b       [W0+0], W4
        cp.l        W4, #0
        bra         z, L_x1s3p_ready32_refuse

        push.l      F8
        push.l      F9
        push.l      F10
        push.l      F11
        push.l      F12
        push.l      F13
        push.l      F14
        push.l      F15
        push.l      F16
        push.l      F17
        push.l      F18
        push.l      F19
        push.l      F20
        push.l      F21
        push.l      F22
        push.l      F23
        push.l      F24
        push.l      F25
        push.l      FCR
        mov.l       #0x7F, W7         ; FCR defaults, exceptions masked
        floatsetup  W7

        mov.l       W3, [W15++]       ; blockSize
        mov.l       W2, [W15++]       ; original pDst

