        lsr.l       W7, #9, W7
        muluu.l    W7, #3, W5
        sub.l       W4, W5, W4
        mov.l       W4, [W15++]       ; stage remainder
        mov.l       W7, W3
        mov.l       [W15-12], W4
        sub.l       #1, W4
        muluu.l    W4, #171, W7
        lsr.l       W7, #10, W7
        muluu.l    W7, #6, W5
        sub.l       W4, W5, W4
        mov.l       W7, [W15++]       ; groups
        mov.l       W4, [W15++]       ; tail

        mov.l       [W0+4], W5
        mov.l       [W0+8], W6
        cp.l        W3, #0
        bra         z, L_x1s3p_ready32_after_triples

