;==============================================================================
L_x1s3p_ready32_start_triple:
        mov.l       [W1++], F24

        mov.l       [W5++], F0
        mov.l       [W5++], F1
        mov.l       [W5++], F2
        mov.l       [W5++], F3
        mov.l       [W5++], F4
